import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { Form, FormBuilder, FormControl, FormGroup, Validators, FormArray } from '@angular/forms';
import { ModalController, NavParams } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-te-apply-exam',
  templateUrl: './te-apply-exam.page.html',
  styleUrls: ['./te-apply-exam.page.scss'],
})
export class TeApplyExamPage implements OnInit {

  studentData: any;
  isForm: FormGroup;
  examList:any = [];
  examLists:any = [];
  submitted:boolean;
  resultList: any = [
    {
      id: 1,
      name: "Cleared"
    },
    {
      id: 2,
      name: "Not Cleared"
    },
    {
      id: 3,
      name: "Not Attended"
    },
    {
      id: 4,
      name: "Yet to Attended"
    }
  ]
  saveData: any;
  isDisabled: boolean;
  StudRegisterList:any = [];
  isUpdating: any;
  buttonOpen: boolean;
  

  constructor(
    private navParams: NavParams,
    private modalCtrl: ModalController,
    private fb: FormBuilder,
    private alert: AlertService,
    private userSession: UserSessionService,
    private datePipe: DatePipe,
    private emisService: EmisService
  ) { }

  ngOnInit() {
    this.initialValidator();
  }

  initialValidator() {
    this.isForm = this.fb.group({
      StemExam: this.fb.array([]),
      isExam: new FormControl('', Validators.required),
    });
  }

  get getPiecesArray() {
    return (<FormArray>this.isForm.get('StemExam'));
  }

  ionViewDidEnter(){
    this.studentData = this.navParams.get('data');
    this.examLists = this.navParams.get('exam');
    this.saveData = this.navParams.get('saveData');
    this.StudRegisterList = this.studentData.StudRegisterList;
    console.log("Student Data",this.studentData, this.saveData);
    if(this.saveData && this.saveData != undefined && this.saveData != null){
      this.isDisabled = true;
      this.buttonOpen = true;
      this.isForm.controls['isExam'].setValue(this.saveData.exam_id);
      this.isForm.controls['isExam'].updateValueAndValidity();
      // const piece = this.fb.group({
      //   IndxId: new FormControl(this.saveData.id, null),
      //   ExamId: new FormControl(this.saveData.exam_id, null),
      //   ExamName: new FormControl(this.saveData.exam, null),
      //   isOtherExam: new FormControl(this.saveData.exam_id, this.saveData.exam_id == 100 ? Validators.required : null),
      //   isOtherExamActive: new FormControl( this.saveData.exam_id == 100 ? true:false, null),
      //   isDate: new FormControl(this.saveData.exam_date, Validators.required),
      //   isRegisterNumber: new FormControl(this.saveData.register_no, Validators.required),
      //   isResult: new FormControl(+this.saveData.result_status, Validators.required)
      // });
      // this.getPiecesArray.push(piece);
    }
    if(this.StudRegisterList.length > 0 && !this.saveData){
      for(let i = 0; i<this.examLists.length; i++){
        let found = false;
        for(let j = 0; j<this.StudRegisterList.length; j++){
          if(this.examLists[i].id == this.StudRegisterList[j].exam_id && this.examLists[i].id != 100){
            found = true;
            break;
          }
        }
        if (!found) {
          this.examList.push(this.examLists[i]);
        }
      }
    }else{
      this.examList = this.examLists;
    }
    
  }

  onExamSelect(res){
    debugger
    let data = typeof res === 'string' ? [res] : res;
    const control = <FormArray>this.isForm.controls['StemExam'];
    for (let i = control.length - 1; i >= 0; i--) {
      control.removeAt(i);
    }
    this.submitted = false;
    for(let i=0; i<data.length; i++){
      const piece = this.fb.group({
        IndxId: new FormControl('', null),
        ExamId: new FormControl(data[i], null),
        ExamName: new FormControl('', null),
        isOtherExam: new FormControl('', data[i] == 100 ? Validators.required : null),
        isOtherExamActive: new FormControl( data[i] == 100 ? true:false, null),
        isDate: new FormControl('', Validators.required),
        isRegisterNumber: new FormControl('', Validators.required),
        isResult: new FormControl('', Validators.required)
      });
      this.getPiecesArray.push(piece);
    }
    this.buttonOpen = true;
    for(let i =0; i<this.isForm.value.StemExam.length; i++){
      for(let k=0;k<this.examList.length; k++){
        if(this.isForm.value.StemExam[i].ExamId == this.examList[k].id){
          this.isForm.controls['StemExam']['controls'][i].controls['ExamName'].setValue(this.examList[k].exam);
        }
      }
      if(this.isDisabled){
        this.isForm.controls['StemExam']['controls'][i].controls['IndxId'].setValue(this.saveData.id);
        this.isForm.controls['StemExam']['controls'][i].controls['ExamId'].setValue(this.saveData.exam_id);
        this.isForm.controls['StemExam']['controls'][i].controls['ExamName'].setValue(this.saveData.exam);
        this.isForm.controls['StemExam']['controls'][i].controls['isOtherExam'].setValue(this.saveData.other_exam);
        this.isForm.controls['StemExam']['controls'][i].controls['isOtherExamActive'].setValue(this.saveData.exam_id == 100 ? true:false);
        this.isForm.controls['StemExam']['controls'][i].controls['isDate'].setValue(this.saveData.exam_date);
        this.isForm.controls['StemExam']['controls'][i].controls['isRegisterNumber'].setValue(this.saveData.register_no);
        this.isForm.controls['StemExam']['controls'][i].controls['isResult'].setValue(+this.saveData.result_status);
      }
    }

    // if(data == 100){
    //   this.isForm.controls['isOtherExam'].setValue('');
    //   this.isForm.controls['isOtherExam'].setValidators(Validators.required);
    //   this.isForm.controls['isOtherExam'].updateValueAndValidity();
    // }else{
    //   this.isForm.controls['isOtherExam'].setValue('');
    //   this.isForm.controls['isOtherExam'].setValidators(null);
    //   this.isForm.controls['isOtherExam'].updateValueAndValidity();
    // }
  }

  onSave(){
    if(this.isForm.valid){
      this.submitted = false;
      let Exams = [];
      for(let i=0; i<this.isForm.value.StemExam.length; i++){
        let id = {
          "id": this.isForm.value.StemExam[i].IndxId,
          "school_id": this.studentData.school_id,
          "student_id": this.studentData.StudId,
          "class_id": this.studentData.class_studying_id,
          "exam_id": this.isForm.value.StemExam[i].ExamId.toString(),
          "exam_date": this.datePipe.transform(this.isForm.value.StemExam[i].isDate, 'yyyy-MM-dd'),
          "other_exam": this.isForm.value.StemExam[i].isOtherExam,
          "register_no": this.isForm.value.StemExam[i].isRegisterNumber,
          "result_status": this.isForm.value.StemExam[i].isResult,
          "user_id": this.userSession.emis_username()
        }
        Exams.push(id);
      }
      let params = {
        "records": Exams
      }
      this.emisService.StudWiseRegister(params).subscribe(res =>{
        if(res.dataStatus){
          this.modalCtrl.dismiss(1);
          this.alert.success(res.message);
        }else{
          this.alert.error(res.message);
        }
      })

    }else{
      this.submitted = true;
      this.alert.error("Please enter valid data");
    }
  }

  onDateChange(event: any, k) {
    if (this.isUpdating) return;
    const selectedDate = new Date(event.detail.value);
    let isActive = false;
    if(selectedDate && !isNaN(selectedDate.getTime())){
      const selectedDateString = this.datePipe.transform(selectedDate, 'yyyy-MM-dd');
      const currentControl = this.isForm.controls['StemExam']['controls'][k].controls['isDate'];
      currentControl.setValue(''); 
      currentControl.updateValueAndValidity();
      for (let i = 0; i < this.isForm.value.StemExam.length; i++) {
        const element = this.isForm.value.StemExam[i];
        if(element.isDate){
          const oldDate = this.datePipe.transform(element.isDate, 'yyyy-MM-dd');
          if(oldDate == selectedDateString){
            isActive = true;
            this.alert.error("You cannot select this date. Already assigned this date of exam");
            currentControl.setValue(''); 
            currentControl.updateValueAndValidity();
            break;
          }
        }
      }
    } 
    
    if(!isActive){
      this.isUpdating = true;
      if(this.studentData.StudRegisterList.length == 0){
        this.isForm.controls['StemExam']['controls'][k].controls['isDate'].setValue(event.detail.value);
        this.isForm.controls['StemExam']['controls'][k].controls['isDate'].updateValueAndValidity();
      }else{
        let isCheck = false;
        for (let p = 0; p < this.studentData.StudRegisterList.length; p++) {
          const element = this.studentData.StudRegisterList[p];
          if(element.exam_date){
            const selectedDateString = this.datePipe.transform(event.detail.value, 'yyyy-MM-dd');
            const oldDate = this.datePipe.transform(element.exam_date, 'yyyy-MM-dd');
            if(oldDate == selectedDateString){
              isCheck = true;
              this.alert.error("You cannot select this date. Already assigned this date of exam");
              const currentControl = this.isForm.controls['StemExam']['controls'][k].controls['isDate'];
              currentControl.setValue(''); 
              currentControl.updateValueAndValidity();
              break;
            }
          }
        }
        if(!isCheck){
          this.isForm.controls['StemExam']['controls'][k].controls['isDate'].setValue(event.detail.value);
          this.isForm.controls['StemExam']['controls'][k].controls['isDate'].updateValueAndValidity();
        }
      }
      this.isUpdating = false;
    }
  }

  goBack(){
    this.modalCtrl.dismiss();
  }

  ionViewWillLeave(){
    this.saveData = '';
    this.buttonOpen = false;
  }
}
